/** Hull points of an original car (fresh copies), or null for an unknown name / an archetype car. */
export function origHull(name: string | null | undefined): { x: number; y: number; z: number }[] | null {
  const h = name ? ORIG_HULLS[name] : undefined;
  return h ? h.map(([x, y, z]) => ({ x, y, z })) : null;
}
